<?php $pageTitle='Dashboard';require __DIR__.'/config/database.php';require __DIR__.'/includes/header.php';$stats=['Book Copies'=>(int)$pdo->query("SELECT COALESCE(SUM(total_copies),0) FROM books")->fetchColumn(),'Available'=>(int)$pdo->query("SELECT COALESCE(SUM(available_copies),0) FROM books")->fetchColumn(),'Members'=>(int)$pdo->query("SELECT COUNT(*) FROM members WHERE status='active'")->fetchColumn(),'Issued'=>(int)$pdo->query("SELECT COUNT(*) FROM loans WHERE status='issued'")->fetchColumn(),'Overdue'=>(int)$pdo->query("SELECT COUNT(*) FROM loans WHERE status='issued' AND due_date<CURDATE()")->fetchColumn()];?><h2>Dashboard</h2><div class="row g-3"><?php foreach($stats as $k=>$v):?><div class="col-md-3 col-lg"><div class="card shadow-sm"><div class="card-body"><div class="text-muted"><?=h($k)?></div><div class="fs-2 fw-bold"><?=$v?></div></div></div></div><?php endforeach;?></div><div class="mt-4"><a class="btn btn-primary me-2" href="books.php">Books</a><a class="btn btn-success me-2" href="members.php">Members</a><a class="btn btn-warning" href="issue.php">Issue / Return</a></div><?php require __DIR__.'/includes/footer.php';